class Solution:
    def longestValidParentheses(self, s: str) -> int:
        def scan(s, opener):
            best = l = r = 0
            for c in s:
                if c == opener:
                    l += 1
                else:
                    r += 1
                if l == r:
                    best = max(best, 2 * r)
                elif r > l:
                    l = r = 0
            return best
        return max(scan(s, "("), scan(s[::-1], ")"))

